import ezdxf, json, os, collections
D = r"C:\Users\DELL\Desktop\AI_CAD\AI_Work\Thang-11\09-11-2026\521109-06"
T = r"C:\Users\DELL\AppData\Local\Temp\ai_cad_521109-06"
codes = ["26-066540", "26-066541", "26-066542", "26-066543", "26-066544", "26-066545"]


def r(v):
    return [float(v[0]), float(v[1])]


for c in codes:
    d = ezdxf.readfile(os.path.join(D, c + ".dxf"))
    ents = []
    for e in d.modelspace():
        t = e.dxftype()
        col = e.dxf.color if e.dxf.hasattr("color") and e.dxf.color not in (0, 256) else 0
        if t == "LINE":
            x = {"t": "LINE", "p1": r(e.dxf.start), "p2": r(e.dxf.end)}
            if e.dxf.hasattr("linetype") and e.dxf.linetype.upper() == "DASHED":
                x["dashed"] = True
        elif t == "ARC":
            x = {"t": "ARC", "c": r(e.dxf.center), "r": e.dxf.radius, "a0": e.dxf.start_angle, "a1": e.dxf.end_angle}
        elif t == "CIRCLE":
            x = {"t": "CIRCLE", "c": r(e.dxf.center), "r": e.dxf.radius}
        elif t == "POINT":
            x = {"t": "POINT", "p": r(e.dxf.location)}
        elif t == "TEXT":
            x = {"t": "TEXT", "p": r(e.dxf.insert), "h": e.dxf.height, "text": e.dxf.text}
        else:
            print("bo qua", t)
            continue
        if col:
            x["color"] = col
        ents.append(x)
    ext = d.header["$EXTMAX"]
    w, h = float(ext[0]), float(ext[1])
    json.dump({"code": c, "w": w, "h": h, "flags": [], "entities": ents},
              open(os.path.join(T, "spec_" + c + ".json"), "w", encoding="utf8"))
    print(c, w, h, len(ents), dict(collections.Counter(e["t"] for e in ents)))

